create table if not exists public.navigations (id bigint generated by default as identity primary key, key varchar(40) not null unique, location varchar(20) not null unique, admin_name varchar(80) not null, enabled boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.navigation_variants (id bigint generated by default as identity primary key, navigation_id bigint not null references public.navigations(id) on delete cascade, locale_id bigint not null references public.locales(id) on delete cascade, status varchar(20) not null default 'published', is_default boolean not null default false, default_flag bigint generated always as (case when is_default then navigation_id else null end) stored, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(navigation_id, locale_id), unique(default_flag));
create table if not exists public.navigation_items (id bigint generated by default as identity primary key, navigation_variant_id bigint not null references public.navigation_variants(id) on delete cascade, parent_id bigint references public.navigation_items(id) on delete cascade, type varchar(20) not null default 'custom', target_entity_type varchar(20), target_entity_id bigint, sort_order integer not null default 0, enabled boolean not null default true, open_in_new_tab boolean not null default false, rel varchar(100), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.navigation_item_translations (id bigint generated by default as identity primary key, navigation_item_id bigint not null references public.navigation_items(id) on delete cascade, locale_id bigint not null references public.locales(id) on delete cascade, label varchar(120) not null, custom_url varchar(500), title_attribute varchar(255), nofollow boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(navigation_item_id, locale_id));
create index if not exists navigation_variants_locale_idx on public.navigation_variants(locale_id);
create index if not exists navigation_items_variant_idx on public.navigation_items(navigation_variant_id);
create index if not exists navigation_items_parent_idx on public.navigation_items(parent_id);
create index if not exists navigation_item_translations_locale_idx on public.navigation_item_translations(locale_id);
alter table public.navigations enable row level security;
alter table public.navigation_variants enable row level security;
alter table public.navigation_items enable row level security;
alter table public.navigation_item_translations enable row level security;
revoke all on table public.navigations, public.navigation_variants, public.navigation_items, public.navigation_item_translations from anon, authenticated;
